2	import { describe, expect, it } from "vitest";
3	import { z } from "zod";
4	import {
5	  HTTP_STATUS_BY_CODE,
6	  fieldErrorsFromZod,
7	  isDomainError,
8	  toActionResult,
9	  toAppError,
10	} from "@/lib/errors";
11	import { FeatureDisabledError } from "@/lib/feature-flags";
12	import { PermissionDeniedError, explain } from "@/lib/permissions";
13	import { InvalidSlugError } from "@/lib/slug";
14	import { AlreadyArchivedError } from "@/lib/soft-delete";
15	import { TenantScopeError } from "@/lib/tenant";
16	import type { OrgId } from "@/types/common";
17	import { makeActor, ORG_A, ORG_B } from "../helpers/factories";
18	
19	const schema = z.object({
20	  title: z.string().min(3),
21	  estimate: z.number().int(),
22	});
23	
24	function permissionError(): PermissionDeniedError {
25	  const actor = makeActor({ role: "viewer" });
26	  const resource = { kind: "organization", orgId: ORG_A } as const;
27	  return new PermissionDeniedError("org:delete", explain(actor, "org:delete", resource));
28	}
29	
30	describe("lib/errors", () => {
31	  it("maps a permission denial to `forbidden` with the decision in meta", () => {
32	    const shape = toAppError(permissionError());
33	    expect(shape.code).toBe("forbidden");
34	    expect(shape.meta?.action).toBe("org:delete");
35	    expect(shape.meta?.reason).toBe("denied_by_role");
36	  });
37	
38	  it("maps a tenant scope violation to `tenant_scope_violation`", () => {
39	    const shape = toAppError(new TenantScopeError(ORG_A, ORG_B));
40	    expect(shape.code).toBe("tenant_scope_violation");
41	    expect(shape.meta?.expectedOrgId).toBe(ORG_A);
42	    expect(shape.message).not.toContain(ORG_B as string);
43	  });
44	
45	  it("maps a disabled feature to `forbidden` and names the flag", () => {
46	    const shape = toAppError(new FeatureDisabledError("webhooks"));
47	    expect(shape.code).toBe("forbidden");
48	    expect(shape.meta?.flag).toBe("webhooks");
49	  });
50	
51	  it("maps double archiving to `conflict`", () => {
52	    const shape = toAppError(new AlreadyArchivedError("Issue", "01ISS"));
53	    expect(shape.code).toBe("conflict");
54	    expect(shape.meta?.entity).toBe("Issue");
55	  });
56	
57	  it("maps an invalid slug to `validation_failed` with a slug field error", () => {
58	    const shape = toAppError(new InvalidSlugError("Admin!", "is reserved"));
59	    expect(shape.code).toBe("validation_failed");
60	    expect(shape.fieldErrors?.slug?.[0]).toContain("is reserved");
61	  });
62	
63	  it("maps a ZodError to field errors keyed by dotted path", () => {
64	    const parsed = schema.safeParse({ title: "no", estimate: 1.5 });
65	    expect(parsed.success).toBe(false);
66	    if (parsed.success) return;
67	
68	    const fields = fieldErrorsFromZod(parsed.error);
69	    expect(Object.keys(fields).sort()).toEqual(["estimate", "title"]);
70	    expect(toAppError(parsed.error).code).toBe("validation_failed");
71	  });
72	
73	  it("falls back to `internal_error` for an unknown throw", () => {
74	    expect(toAppError(new Error("boom")).code).toBe("internal_error");
75	    expect(toAppError("boom").code).toBe("internal_error");
76	    expect(toAppError("boom").message).toContain("Something went wrong");
77	  });
78	
79	  it("recognises exactly the domain error classes", () => {
80	    expect(isDomainError(permissionError())).toBe(true);
81	    expect(isDomainError(new TenantScopeError(ORG_A, ORG_B))).toBe(true);
82	    expect(isDomainError(new InvalidSlugError("x", "too short"))).toBe(true);
83	    expect(isDomainError(new Error("boom"))).toBe(false);
84	    expect(isDomainError(null)).toBe(false);
85	  });
86	
